cd /app; cat >> notes/PRC-501.md <<'EOF'

## 設計（T2・解が1つの不具合修正）
自明: 解は「切り捨てに戻す」1通り。丸め方針の変更案は README/コメントが切り捨てを明言しており不採用。共通 helper への集約は範囲外（別チケット候補）。
## テストリスト（層: シェル単体）
1. price 999→899  2. quote 999→"quote: 899"  3. invoice 999→"member total 899"  4. statement 999→"statement member 899"  5. 端数なし(500→450,1000→900)は既存。
書かないテスト: 負数・非数入力（仕様外、本件の範囲外）。
EOF
echo "工程: 4テスト実装(赤確認)。次: 5実装" > .dev-state.md
cat > tests/price_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
EOF
cat > tests/statement_test.sh <<'EOF'
#!/bin/bash
fail=0
[ -n "$(bash lib/statement.sh 1000)" ] || { echo "statement prints nothing"; fail=1; }
[ "$(bash lib/statement.sh 999)" = "statement member 899" ] || { echo "statement 999"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo rc=$?
